import React from 'react'
import { useNavigate } from 'react-router-dom'
import NavBar from '../Components/NavBar'
import Footer from '../Components/Footer'
import './advertisements.css' // Add CSS here

const posters = [
  {
    id: 1,
    title: 'Awesome Poster 1',
    imageUrl: '/Images/home1.jpg',
    description: 'Description for Poster 1'
  },
  {
    id: 2,
    title: 'Awesome Poster 2',
    imageUrl: '/images/poster2.jpg',
    description: 'Description for Poster 2'
  }
]

export default function Advertisements() {
  const navigate = useNavigate()

  const goToDetail = (poster) => {
    // Pass poster data via state
    navigate(`/advertisement/${poster.id}`, { state: poster })
  }

  return (
    <div>
      <NavBar />

      <div className="posters-container">
        {posters.map((poster) => (
          <div
            key={poster.id}
            className="poster-card"
            onClick={() => goToDetail(poster)}
          >
            <img src={poster.imageUrl} alt={poster.title} className="poster-image" />
            <h3 className="poster-title">{poster.title}</h3>
          </div>
        ))}
      </div>

      <Footer />
    </div>
  )
}
